    /*Searches Table*/
-- Drop and recreate Searches table
DROP TABLE IF EXISTS searches;
CREATE TABLE searches (
    id INT AUTO_INCREMENT PRIMARY KEY,
    search_term VARCHAR(255) NOT NULL,
    state_id INT NULL,
    price_range VARCHAR(50) NULL,
    user_ip VARCHAR(45) NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (state_id) REFERENCES states(id)
);

    /*Attraction_Details Table*/
-- Drop and recreate Attraction_Details table
DROP TABLE IF EXISTS attraction_details;

CREATE TABLE attraction_details (
  id INT AUTO_INCREMENT PRIMARY KEY,
  attraction_id INT NOT NULL,
  attraction_name VARCHAR(100) NOT NULL,
  adult_price DECIMAL(10,2) NOT NULL,
  youth_price DECIMAL(10,2) NOT NULL,
  foreign_price DECIMAL(10,2) NOT NULL,
  image VARCHAR(255) NOT NULL,
  image2 VARCHAR(255) NOT NULL,
  image3 VARCHAR(255) NOT NULL,
  image4 VARCHAR(255) NOT NULL,
  attraction_description TEXT,
  attraction_expectation TEXT NOT NULL,
  location TEXT NOT NULL,
  FOREIGN KEY (attraction_id) REFERENCES attractions(id)
);

INSERT INTO attraction_details (attraction_id, attraction_name, adult_price, youth_price, foreign_price, image, image2, image3, image4, attraction_description, attraction_expectation, location) VALUES
(1, 'PETRONAS Twin Towers', 60.00, 45.00, 80.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/petronas.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/petronas2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/petronas3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/petronas4.jpg', 'Iconic landmark in the heart of Kuala Lumpur, the Petronas Twin Towers stand 452 metres tall and showcase a striking blend of modern design and Islamic-inspired architecture. The two towers are linked by a Skybridge on the 41st and 42nd floors, offering unique views of the city skyline. At the base, visitors can explore the Suria KLCC shopping mall, musical fountains, and the lush KLCC Park. A symbol of Malaysia''s progress and ambition, it is a must-visit attraction for any traveller.', 'Located in Kuala Lumpur, Malaysia, the Petronas Twin Towers are a must-visit attraction that takes you on a journey through Malaysia''s history, culture, and architectural excellence. Plus, the Skybridge connecting these tallest twin towers in the world is the highest two-story bridge globally, offering unparalleled views.Start your journey with interactive displays showing details of the towers''construction process. Take a 170-meter elevator ride to the Skybridge, where you''ll have a unique vantage point between the towers. Continue to level 86 for a closer look at Malaysia''s vision, accompanied by stunning views of Kuala Lumpur. Before you head home, swing by the gift shop or the Suria KLCC Mall for some souvenirs to commemorate your visit. Get ready for an eye-opening experience at the Petronas Twin Towers—a must-see stop on your Malaysian adventure! When visiting Kuala Lumpur, Malaysia, there is only one attraction that you definitely can''t miss, and it''s the iconic PETRONAS Twin Towers. Standing at an incredible height of 451.9 meters, the 88-storey Petronas Twin Towers are the number one architectural landmark of Kuala Lumpur and remain the world''s tallest twin structures up till today. If you think the towers look impressive from the outside, just wait until you get inside with the PETRONAS Towers tickets! After you ascend 170 meters in a futuristic, high-speed lift and ascend to level 86, the doors open to a breathtaking view of Malaysia''s capital that you won''t be able to capture anywhere else in the city.\r\n\r\nStep onto a unique connecting structure, the world''s highest two-story bridge! The skybridge connects the two towers together on their 41st and 42nd floors and is located 170m above ground. Learn about the history and construction of this stunning masterpiece, and don''t forget to pick up a souvenir or two at the gift shop of PETRONAS Twin Towers in Kuala Lumpur!', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d7967.519522487064!2d101.70672824022647!3d3.1579170372697614!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31cc37d12d669c1f%3A0x9e3afdd17c8a9056!2sPetronas%20Twin%20Towers!5e0!3m2!1sen!2smy!4v1756023809848!5m2!1sen!2smy'),
(5, 'Aquarium KLCC', 40.00, 25.00, 60.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/aquarium.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/aquarium2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/aquarium3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/aquarium4.jpg', 'Aquaria KLCC is a world-class oceanarium located beneath the Kuala Lumpur Convention Centre, just a short walk from the Petronas Twin Towers. It features over 5,000 aquatic and land-bound creatures in themed exhibits, including a spectacular 90-metre underwater tunnel with sharks, rays, and colourful fish swimming overhead. Interactive displays and feeding demonstrations make it an engaging experience for visitors of all ages. It''s a great indoor attraction that combines fun with education and is perfect for families and marine-life enthusiasts.', 'At Aquaria KLCC, visitors can expect an immersive journey through Malaysia''s rich marine and freshwater ecosystems. Located beneath the Kuala Lumpur Convention Centre, this world-class oceanarium features over 5,000 land and aquatic creatures. You''ll walk through themed zones that showcase everything from local river habitats to the open ocean. One of the highlights is the 90-meter underwater tunnel, where sharks, stingrays, and giant groupers swim overhead, giving a panoramic view of life under the sea. Interactive feeding sessions, educational displays, and touch pools allow for a hands-on experience, making it suitable for families, students, and marine enthusiasts alike.\r\n\r\nExpect a mix of education and entertainment—you''ll leave with both memorable photos and a deeper understanding of aquatic life. The aquarium is indoors, so it''s a great option even during rainy days in Kuala Lumpur.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1991.8874621008913!2d101.71351845!3d3.1539618499999995!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31cc37d39d319733%3A0x68a27ec3fd8f6bed!2sAquaria%20KLCC!5e0!3m2!1sen!2smy!4v1757078512577!5m2!1sen!2smy'),
(49, 'Berjaya Times Square Theme Park', 62.00, 40.00, 90.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/berjayaThemePark.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/berjayaThemePark2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/berjayaThemePark3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/berjayaThemePark4.jpg', 'Nestled within the colossal Berjaya Times Square complex in central Kuala Lumpur, this indoor theme park spans a massive 133,000 sq ft and holds the title of Malaysia’s largest covered theme park. Opened in 2003 and formerly known as Cosmo’s World, it features over a dozen attractions divided into two main zones—Galaxy Station for thrill-seekers and Fantasy Garden for kid-friendly fun. Among the standout rides is the Supersonic Odyssey, a high-speed indoor roller coaster by Intamin, complete with inversions and a heartline roll. Other attractions include carousels, bumper cars, junior pirate ships, and even a holographic “waterless aquarium” experience.', 'Berjaya Times Square Theme Park offers an exciting indoor adventure right in the heart of Kuala Lumpur. Spread across multiple floors inside Berjaya Times Square mall, it is one of Malaysia’s largest indoor theme parks, making it perfect for visitors seeking fun regardless of the weather.\r\n\r\nExpect thrilling rides like the Supersonic Odyssey roller coaster and the DNA Mixer, as well as family-friendly attractions in the Fantasy Garden zone. Younger visitors can enjoy interactive games, carnival-style rides, and colorful themed areas designed just for kids.\r\n\r\nThe park’s indoor setting provides a safe and comfortable environment, with easy access to shopping and dining options within the mall. Whether you’re a thrill-seeker or a family with children, the theme park offers a mix of adrenaline and entertainment all under one roof.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3983.8199094295405!2d101.70797627473033!3d3.1421983968332516!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31cc362890539213%3A0x1fd9aab834792386!2sBerjaya%20Times%20Square%20Theme%20Park!5e0!3m2!1sen!2smy!4v1757078750211!5m2!1sen!2smy'),
(4, 'Batu Caves & Cave Villa', 7.00, 7.00, 7.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/batuCaves.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/batuCaves2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/batuCaves3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/batuCaves4.jpg', 'Batu Caves is one of Malaysia’s most iconic landmarks, located just outside Kuala Lumpur. It is a limestone hill that houses a series of caves and cave temples, most famously the Temple Cave with its towering 42.7-meter golden statue of Lord Murugan. This sacred Hindu site attracts worshippers and tourists alike, especially during the Thaipusam festival.', 'Visitors can expect a climb up 272 colorful steps leading to the main cave, where intricate Hindu shrines and statues await. Along the way, friendly monkeys often roam the stairways, adding to the lively atmosphere. The caves feature stunning limestone formations, religious art, and breathtaking views from the top. Dress modestly out of respect for the religious site, and be prepared for physical activity due to the steep staircase.\r\nInside Cave Villa, visitors will find colorful murals, statues, and dioramas depicting Hindu epics such as the Ramayana. There are also cultural displays, koi ponds, and artwork installations that provide a more relaxed and visually engaging experience compared to the climb up Batu Caves. The space is more leisurely, making it suitable for those who prefer a gentle walk while enjoying art and culture. Expect a quieter, more reflective atmosphere compared to the bustling temple caves above.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3983.4500030794866!2d101.68025757473067!3d3.2376596967374334!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31cc470cdf03cc3d%3A0x989b945fdf4298c3!2sCave%20Villa!5e0!3m2!1sen!2smy!4v1757079881747!5m2!1sen!2smy'),
(6, 'Zoo Negara Malaysia', 38.00, 20.00, 45.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/zoo.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/zoo2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/zoo3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/zoo4.jpg', 'Zoo Negara, located just outside Kuala Lumpur, is Malaysia’s National Zoo and home to over 5,000 animals from more than 400 species. Spanning 110 acres, the zoo is managed by the Malaysian Zoological Society and is dedicated to conservation, education, and research. One of its main highlights is the Giant Panda Conservation Centre, where visitors can meet Malaysia’s resident giant pandas, Xing Xing and Liang Liang.', 'Visitors can expect a full day exploring themed exhibits such as the Reptile House, Bird Aviary, Mammal Kingdom, and Aquarium. The zoo’s open-concept enclosures are designed to mimic natural habitats, giving guests a closer look at animals in a more comfortable environment. Families will enjoy animal shows, educational talks, and interactive feeding sessions. Comfortable walking shoes are recommended, as the zoo is large and requires plenty of walking. Expect an educational yet entertaining experience suitable for visitors of all ages.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3983.5569603379863!2d101.75624387473053!3d3.2103487967648285!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31cc39b60a831fe1%3A0xf2c800c702db7b2f!2sZoo%20Negara%20Malaysia!5e0!3m2!1sen!2smy!4v1757080455211!5m2!1sen!2smy'),
(41, 'ATV Kundasang', 80.00, 70.00, 120.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/atv.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/atv2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/atv3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/atv4.jpg', 'ATV Kundasang is an adventurous outdoor attraction set against the breathtaking backdrop of Mount Kinabalu and the rolling hills of Kundasang, Sabah. Known for its cool climate, scenic landscapes, and rustic countryside charm, this experience allows visitors to explore the highlands in a fun and thrilling way—by riding all-terrain vehicles (ATVs) across rugged trails, farms, and panoramic viewpoints. It’s a must-try activity for those seeking a blend of adventure and nature.', 'Visitors can expect an exciting ride through a variety of terrains, from muddy paths and grassy slopes to village roads and open fields. Guided tours are available, making the activity safe even for beginners, with instructors providing basic training and safety gear before the ride. The ATV routes often pass through local farmlands, vegetable gardens, and scenic hillsides, giving guests a closer look at Kundasang’s rural lifestyle and natural beauty. One of the highlights is reaching elevated viewpoints where riders are rewarded with panoramic vistas of Mount Kinabalu, especially stunning on clear days. Along the way, you’ll also encounter cool breezes, vibrant greenery, and picture-perfect landscapes that are ideal for photography.The experience is flexible, with options for short leisure rides or longer, more adventurous trails for thrill-seekers. Families, couples, or groups of friends will all find it enjoyable, as it combines a sense of adventure with the calm beauty of the highlands.ATV Kundasang is more than just a ride—it’s an immersive way to explore the heart of Sabah’s countryside, feel the rush of outdoor adventure, and create unforgettable memories surrounded by nature’s splendor.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3967.929197204313!2d116.58347347474864!3d6.004460693980709!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x323b99bd45124ed9%3A0xb504514bb192f96d!2sATV%20Borneo%20Adventure%20Sport!5e0!3m2!1sen!2smy!4v1757080772948!5m2!1sen!2smy'),
(42, 'Sabah State Museum', 2.00, 2.00, 2.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/museum.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/museum2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/museum3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/museum4.jpg', 'The Sabah State Museum, located in Kota Kinabalu, is the main cultural and historical museum of Sabah. Established in 1965, the museum showcases the rich heritage of the state, from its indigenous cultures and traditional crafts to its natural history and archaeology. The museum complex also includes the Science and Education Centre, the Sabah Art Gallery, and the Heritage Village, which features traditional houses of Sabah''s diverse ethnic groups.', 'Visitors can expect to explore a wide range of exhibits, including ethnographic displays of traditional costumes, tools, and musical instruments, as well as archaeological artifacts and natural history specimens. The Heritage Village offers a unique outdoor experience where guests can step inside life-sized traditional houses, providing insight into Sabah''s many indigenous communities. The museum is informative yet accessible, making it ideal for history enthusiasts, students, and families who want to learn more about the cultural diversity and heritage of Sabah.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3968.247436284362!2d116.071469!3d5.9606126999999995!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x323b69b0cf7e462f%3A0xdc84a51da7164520!2sSabah%20State%20Museum!5e0!3m2!1sen!2smy!4v1757129637283!5m2!1sen!2smy'),
(37, 'Mount Kinabalu', 120.00, 0.00, 250.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/mount.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/mount2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/mount3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/mount4.jpg', 'Mount Kinabalu, standing at 4,095 meters, is the highest peak in Southeast Asia and the crown jewel of Sabah, Malaysia. Located within Kinabalu Park, a UNESCO World Heritage Site, the mountain is renowned for its incredible biodiversity, with thousands of plant species, rare orchids, and unique wildlife. It is a sacred site for the local Kadazandusun people, who hold deep spiritual connections to the mountain.', 'Climbing Mount Kinabalu is a bucket-list adventure. Visitors can expect a challenging but rewarding trek, usually spread across two days, starting from lush rainforest trails and leading to rocky alpine landscapes near the summit. The highlight is catching the sunrise at Low’s Peak, where breathtaking views stretch across Sabah and beyond. A climbing permit, guide, and prior booking are required, as the number of climbers is limited daily. For those not climbing, Kinabalu Park offers scenic walking trails, gardens, and opportunities to enjoy the cool mountain air while admiring the majestic peak.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d15869.64022462067!2d116.54852394379934!3d6.075312902571248!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x323ba2565e9224cb%3A0x2281c3fec0a9c05e!2sMount%20Kinabalu!5e0!3m2!1sen!2smy!4v1757129959093!5m2!1sen!2smy'),
(40, 'Mari Mari Cultural Village', 130.00, 80.00, 200.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/village.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/village2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/village3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/village4.jpg', 'Mari Mari Cultural Village, located in the countryside just outside Kota Kinabalu, is a living museum that showcases the rich cultural heritage of Sabah’s indigenous ethnic groups. The village preserves traditional houses, lifestyles, and practices of tribes such as the Kadazan-Dusun, Rungus, Lundayeh, Bajau, and Murut, offering visitors a glimpse into Sabah’s diverse cultural roots.', 'Visitors can expect an immersive cultural journey filled with demonstrations of traditional crafts, dances, and rituals. You''ll see authentic longhouses, taste local delicacies, and watch cultural performances that bring history to life. Friendly guides share stories and customs, making the experience both entertaining and educational. Guests can try hands-on activities such as blowpipe shooting, fire-making, or sampling rice wine. The visit typically ends with a lively cultural show, leaving you with a deeper appreciation for Sabah’s indigenous traditions.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3968.1514071781125!2d116.198571077309!3d5.973877678568545!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x323b6988ac593f07%3A0x3b44160e4548a01b!2sMari%20Mari%20Cultural%20Village!5e0!3m2!1sen!2smy!4v1757130168274!5m2!1sen!2smy'),
(38, 'Semporna Islands Hopping, Snorkelling, Hiking', 355.00, 300.00, 400.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/semporna.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/semporna2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/semporna3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/semporna4.jpg', 'Semporna, located in Sabah’s east coast, is the gateway to some of the most breathtaking islands in Malaysia, including Sipadan, Mabul, and Mataking. Famous for its crystal-clear waters and vibrant marine life, Semporna is a paradise for divers, snorkelers, and nature lovers. Beyond its waters, the surrounding islands also offer scenic hiking opportunities with panoramic ocean views.', 'Island-hopping tours usually include stops at multiple islands where visitors can snorkel among colorful coral reefs, spot sea turtles, and relax on white sandy beaches. Hiking trails on certain islands reward adventurers with elevated viewpoints perfect for photography. Expect boat rides, sunny weather, and a mix of relaxation and adventure. Snorkeling gear is often provided, but bringing your own ensures comfort. Sunscreen, light clothing, and waterproof bags are essential for the trip. The experience is both exhilarating and peaceful, offering the chance to enjoy Sabah’s tropical paradise from land and sea.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1988.816994360987!2d118.61501143852091!3d4.478911798873863!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x323fff7f6c2e5a8f%3A0xbe3ace44abd2068!2zU2VhZmVzdCBKZXR0eSDmtbfkuLDnoIHlpLQ!5e0!3m2!1sen!2smy!4v1757130927371!5m2!1sen!2smy'),
(39, 'Desa Dariy Farm', 75.00, 50.00, 100.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/farm.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/farm2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/farm3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/farm4.jpg', 'Desa Dairy Farm, often called the “Little New Zealand of Sabah,” is located in Kundasang at the foothills of Mount Kinabalu. The farm is famous for its scenic landscape of rolling green pastures, cool mountain air, and black-and-white Friesian cows. It is one of Sabah’s main suppliers of fresh milk and dairy products, making it both a tourist attraction and a working farm.', 'Visitors can expect a refreshing countryside experience with panoramic views of Mount Kinabalu as a backdrop. Families and travelers can watch cows being milked, learn about dairy production, and enjoy freshly made products like milk, ice cream, and cheese. The farm also has areas where children can feed calves and goats, making it a fun and interactive outing. The cool highland weather and picturesque scenery make Desa Dairy Farm a popular stop for photography and relaxation.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d126972.50721746561!2d116.44127449726562!3d6.009722700000026!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x323b99a781f4934d%3A0x9dff6dfc9e292273!2sDesa%20Dairy%20Farm%20Entrance!5e0!3m2!1sen!2smy!4v1757131177133!5m2!1sen!2smy'),
(2, 'KL Tower Malaysia', 30.00, 0.00, 40.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/kltower.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/kltower2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/kltower3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/kltower4.jpg', 'KL Tower, officially known as Menara Kuala Lumpur, is one of the city’s most recognizable landmarks and one of the tallest telecommunications towers in the world. Standing at 421 meters, it serves both as a broadcasting tower and a major tourist attraction, offering panoramic views of Kuala Lumpur’s skyline.', 'Visitors can expect stunning 360-degree city views from the Observation Deck and the open-air Sky Deck, which is even higher than the Petronas Twin Towers'' viewing platform. Thrill-seekers can experience the glass-floored Sky Box, which extends out from the tower for a heart-racing photo opportunity. The tower also features cultural shows, a mini zoo, and an upscale revolving restaurant for dining with a view. Evening visits are especially popular for sunset and night views of the glittering cityscape.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3983.779205496415!2d101.7011683247303!3d3.1528441968225374!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31cc482b1dcd5813%3A0x106058ce3bc33aba!2sMenara%20Kuala%20Lumpur!5e0!3m2!1sen!2smy!4v1757131587156!5m2!1sen!2smy'),
(3, 'Putrajaya Pink Mosque and River Cruise', 65.00, 30.00, 70.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/mosque.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/mosque2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/mosque3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/mosque4.jpg', 'The Putra Mosque, famously known as the Pink Mosque due to its rose-colored granite, is the most iconic landmark in Putrajaya. Built beside the scenic Putrajaya Lake, it blends modern architecture with traditional Islamic design, inspired by Persian and Malay elements. The mosque can accommodate over 10,000 worshippers and is one of Malaysia’s most beautiful places of worship.', 'Visitors can expect to admire its impressive pink dome, elegant minaret, and intricate interior design. Non-Muslim visitors are welcome outside of prayer times, with proper attire provided at the entrance. The mosque’s location by the lake offers excellent photo opportunities, especially at sunset. A visit here provides both cultural insight and serene surroundings.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3984.5809209872755!2d101.68663807472943!3d2.936070197040238!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31cdb61818046d5d%3A0x53f252ce4a40a088!2sMasjid%20Putra!5e0!3m2!1sen!2smy!4v1757131900307!5m2!1sen!2smy'),
(28, 'ESCAPE Penang', 188.00, 150.00, 220.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/escape.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/escape2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/escape3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/escape4.jpg', 'ESCAPE Penang is an award-winning outdoor theme park located in Teluk Bahang, Penang. Known for its eco-friendly design and adventurous spirit, the park combines thrilling rides with natural landscapes, offering activities that reconnect visitors with outdoor play. It is divided into zones such as Adventureplay and Waterplay, making it suitable for all ages.', 'Visitors can expect adrenaline-pumping activities like ziplining, climbing towers, obstacle courses, and the world''s longest tube water slide. Families can enjoy water attractions, tree climbs, and fun jungle-themed games, while children have their own play zones designed for safe adventure. The park encourages active participation, so be ready to get moving, climb, slide, and splash. Comfortable sportswear, swimwear, and a sense of adventure are must-haves for the day.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3971.783905439598!2d100.21146307474426!3d5.449740494529765!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x304ac3a45d25df75%3A0xe55b46784fbcb260!2sESCAPE%20Penang!5e0!3m2!1sen!2smy!4v1757132158035!5m2!1sen!2smy'),
(29, 'Penang History Gallery at George Town', 35.00, 10.00, 45.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/gallery.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/gallery2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/gallery3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/gallery4.jpg', 'The Penang History Gallery, located in George Town, is a cultural and educational attraction that highlights the rich history and heritage of Penang. Through carefully curated exhibits, it showcases the island’s journey from its early settlement days, colonial influences, multicultural communities, and its recognition as a UNESCO World Heritage Site.', 'Visitors can expect engaging displays of artifacts, photographs, and interactive exhibits that bring Penang''s past to life. The gallery offers insights into the diverse cultures—Malay, Chinese, Indian, and European—that shaped the island’s unique identity. It’s an informative stop for history lovers and travelers who want to better understand George Town''s background while exploring its heritage streets. Expect a compact but enriching experience that pairs well with walking tours around George Town.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3971.9830505543023!2d100.337277774744!3d5.4195449945596925!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x304ac3cad438bdcd%3A0x508e7f772e2ca89!2sPenang%20History%20Gallery!5e0!3m2!1sen!2smy!4v1757132479452!5m2!1sen!2smy'),
(30, 'Tech Dome Penang', 28.00, 20.00, 35.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/techdome.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/techdome2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/techdome3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/techdome4.jpg', 'Tech Dome Penang is a science and technology discovery center located inside the iconic Komtar building in George Town, Penang. Opened in 2016, it serves as Penang’s first science center, aiming to spark interest in STEM (Science, Technology, Engineering, and Mathematics) through interactive learning and hands-on experiences.', 'Visitors can expect over 120 interactive exhibits spread across themes like Robotics, Space Exploration, Optics, Life Tech, and Information Technology. Highlights include a 3D theater, a giant slide, and fun science demonstrations suitable for both children and adults. The center encourages exploration and curiosity, making it a great stop for families, students, and tech enthusiasts. Expect a blend of education and entertainment where learning science feels fun and engaging.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3972.018797766708!2d100.3304059584424!3d5.414107027250065!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x304ac39435c00001%3A0xfe6252535df1cda8!2sTech%20Dome%20Penang!5e0!3m2!1sen!2smy!4v1757132889967!5m2!1sen!2smy'),
(25, 'The Habitat Penang Hill', 60.00, 40.00, 70.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/penanghill.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/penanghill2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/penanghill3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/penanghill4.jpg', 'The Habitat Penang Hill is an award-winning eco-attraction located on Penang Hill, offering visitors a chance to experience the island’s ancient rainforest, estimated to be over 130 million years old. It combines nature, conservation, and education with breathtaking views of George Town, the Penang Bridge, and even as far as Langkawi on clear days.', 'Visitors can expect a serene walk along the 1.6 km nature trail surrounded by lush rainforest. Highlights include the Langur Way Canopy Walk, one of the longest two-span bridges in the world, and the Curtis Crest Treetop Walk, the highest viewing point on Penang Island with 360-degree panoramic views. Along the way, you may encounter native flora and fauna, butterflies, and exotic bird species. The Habitat also offers guided tours, educational exhibits, and eco-experiences, making it perfect for nature lovers, families, and photographers. Expect a refreshing escape from the city with cool highland air and stunning natural beauty.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3971.9434520031555!2d100.26586257474408!3d5.42556249455374!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x304ac27b82385471%3A0x2974f8d6b01c821b!2sThe%20Habitat%20Penang%20Hill!5e0!3m2!1sen!2smy!4v1757133162494!5m2!1sen!2smy'),
(26, 'The TOP Penang', 70.00, 60.00, 80.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/toppenang.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/toppenang2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/toppenang3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/toppenang4.jpg', 'The TOP Penang is a family-friendly entertainment and lifestyle attraction located within the iconic Komtar Tower, George Town’s tallest skyscraper. It features a wide variety of attractions, from observation decks to themed adventure zones, making it one of Penang’s must-visit destinations for fun and sightseeing.', 'Visitors can expect panoramic views of George Town and beyond from the Rainbow Skywalk, a glass walkway on the 68th floor, and the Observatory Deck, offering a thrilling bird''s-eye perspective of the city. Beyond the views, The TOP houses family attractions such as the Jurassic Research Centre, Tech Dome (science discovery center), Ocean Explorer, and a fun indoor theme park environment. Dining options are also available, including rooftop restaurants with scenic city views. Whether you''re after adrenaline, family activities, or simply stunning photo opportunities, The TOP Penang has something for everyone.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3972.0165153705348!2d100.32697467474397!3d5.414454394564737!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x304ac395ce63cafb%3A0x786a38ba7f1ba486!2sThe%20TOP%20Penang%2C%20Theme%20Park%20Penang!5e0!3m2!1sen!2smy!4v1757133494725!5m2!1sen!2smy'),
(27, 'Kek Lok Si Temple', 2.00, 2.00, 2.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/temple.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/temple2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/temple3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/temple4.jpg', 'Kek Lok Si Temple, located in Air Itam, Penang, is the largest Buddhist temple in Malaysia and one of Southeast Asia’s most important pilgrimage sites. Built over a century ago, the temple complex blends Chinese, Thai, and Burmese architectural styles. It is especially famous for its towering Goddess of Mercy (Kuan Yin) statue and the stunning Pagoda of Ten Thousand Buddhas.', 'Visitors can expect to explore sprawling temple grounds filled with intricately decorated halls, prayer chambers, gardens, and cultural relics. Climbing up to the Pagoda offers beautiful panoramic views of Penang, while the Kuan Yin statue and surrounding pavilions provide serene spots for reflection. During Chinese New Year, the temple is illuminated with thousands of lanterns, creating a magical festive atmosphere. Modest attire is recommended, as it is a place of worship. Expect a mix of spirituality, culture, and breathtaking architecture.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3972.1137160280655!2d100.27103767474377!3d5.399641294579432!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x304ac2185dfc8665%3A0x2c9084ea7f433ec4!2sKek%20Lok%20Si%20Temple!5e0!3m2!1sen!2smy!4v1757229638081!5m2!1sen!2smy'),
(43, 'Gunung Gading', 10.00, 5.00, 15.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/gading.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/gading2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/gading3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/gading4.jpg', 'Gunung Gading National Park, located in Lundu, Sarawak, is a protected area famous as one of the best places in the world to see the Rafflesia, the largest flower on Earth. The park, named after Mount Gading, also features lush rainforest, diverse wildlife, and scenic waterfalls, making it a popular spot for both nature lovers and hikers.', 'Visitors can expect guided treks through the jungle to view the rare Rafflesia in bloom (which only lasts a few days at a time). Even outside of the blooming season, the park offers rewarding hikes with well-marked trails leading to waterfalls and mountain viewpoints. Wildlife enthusiasts may spot various birds, insects, and small mammals along the way. Be prepared for a humid rainforest environment—comfortable walking shoes, insect repellent, and plenty of water are essential. Expect a mix of adventure, education, and natural beauty in one visit.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d15952.326179148502!2d109.82541273299502!3d1.6906304023031524!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31fb2728d1a5a10d%3A0x3f430228d3e8dcbd!2sTaman%20Negara%20Gunung%20Gading%2C%2094500%20Lundu%2C%20Sarawak!5e0!3m2!1sen!2smy!4v1757229862600!5m2!1sen!2smy'),
(44, 'Gunung Mulu', 15.00, 10.00, 20.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/mulu.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/mulu2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/mulu3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/mulu4.jpg', 'Gunung Mulu National Park, located in northern Sarawak, is a UNESCO World Heritage Site renowned for its extraordinary limestone karst formations, vast cave systems, and pristine rainforest. It is home to the world’s largest cave chamber (Sarawak Chamber), one of the world’s longest networks of caves, and the striking limestone pinnacles of Mount Api. The park is a paradise for adventurers, cavers, and nature enthusiasts alike.', 'Visitors can expect a mix of guided cave explorations, jungle treks, and breathtaking natural wonders. Popular highlights include the Deer Cave, where millions of bats fly out at dusk in a spectacular display; the Clearwater Cave, known for its underground river; and the challenging trek to the Pinnacles, a dramatic spire-like rock formation. The park also offers canopy walks, river cruises, and opportunities to spot diverse flora and fauna in one of the world''s richest ecosystems. Be prepared for physical activity, tropical humidity, and awe-inspiring scenery at every turn.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d15919.501657797986!2d114.91970024356728!3d4.045833134845864!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x321855c3fda825db%3A0x300748b3384fc6a0!2sMount%20Mulu!5e0!3m2!1sen!2smy!4v1757230298312!5m2!1sen!2smy'),
(45, 'Royal Kuching River Cruise', 69.00, 50.00, 100.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/kuchingcruise.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/kuchingcruise2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/kuchingcruise3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/kuchingcruise4.jpg', 'The Royal Kuching Cruise offers a relaxing river journey along the Sarawak River in Kuching, the capital of Sarawak. It provides a unique perspective of the city’s blend of old-world charm and modern development, passing by historic landmarks, cultural villages, and scenic riverbanks.', 'Visitors can expect a leisurely cruise with views of Kuching’s iconic sites such as the Astana (Governor’s Residence), the striking Sarawak State Legislative Assembly Building, and the Kuching Waterfront. Along the riverbanks, you’ll also spot traditional Malay kampung houses, Chinese temples, and glimpses of daily local life. Evening cruises are particularly popular, offering beautiful sunset views and the chance to see the city lights reflect on the water. Some cruises include cultural performances on board, adding an extra layer of entertainment. Expect a calm, scenic, and memorable way to experience Kuching''s charm.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3988.341224240356!2d110.34458037472508!3d1.5591174984263168!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31fba7a25fb88c87%3A0x4a28b4ddb352d951!2sRoyal%20Kuching%20Cruise!5e0!3m2!1sen!2smy!4v1757230638761!5m2!1sen!2smy'),
(46, 'Bako National Park', 10.00, 10.00, 20.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/bako.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/bako2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/bako3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/bako4.jpg', 'Bako National Park, located about 37 km from Kuching, is Sarawak’s oldest national park and one of the best places to experience the natural beauty of Borneo. Despite its relatively small size, the park is incredibly diverse, featuring mangroves, dipterocarp forests, swamps, and beaches all within a single area. It is most famous for being home to the rare proboscis monkey, a species found only in Borneo. Other wildlife such as silvered leaf monkeys, wild boars, long-tailed macaques, and a wide variety of bird species also thrive here.', 'Visitors can expect an immersive jungle experience that combines trekking, wildlife spotting, and coastal scenery. The park has a network of well-marked trails ranging from easy walks to full-day hikes, leading to hidden waterfalls, secluded beaches, and scenic cliff viewpoints. The most iconic spot is the Sea Stack, a dramatic rock formation shaped by waves over centuries. Wildlife sightings are common, especially early in the morning or late in the afternoon, so patience and a keen eye are rewarded.\r\n\r\nBoat rides are part of the journey, as visitors must travel across the river to reach the park entrance, adding to the adventure. Facilities are basic compared to city attractions, so it’s best to carry essentials like water, insect repellent, and comfortable walking shoes. Expect a rugged yet rewarding experience, offering a true taste of Borneo’s wild side.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d31904.74308930106!2d110.42820423866594!3d1.6851009411520224!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31fa532cb6e56807%3A0x5abbf314c5effda6!2sBako%20National%20Park!5e0!3m2!1sen!2smy!4v1757230916377!5m2!1sen!2smy'),
(47, 'Kuching City Tour', 20.00, 10.00, 25.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/kuchingtour.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/kuchingtour2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/kuchingtour3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/kuchingtour4.jpg', 'Kuching, the capital of Sarawak, is often described as one of the most charming cities in Southeast Asia. Known as the “Cat City” (the word kuching means cat in Malay), it combines old-world heritage with modern development, creating a unique blend of history, culture, and lifestyle. The city is set along the Sarawak River, giving it a relaxed riverside atmosphere while showcasing colonial-era architecture, Chinese temples, Malay kampungs, and colorful street art. A Kuching City Tour offers a comprehensive introduction to this multicultural capital, where traditions of the Malay, Chinese, Indian, and indigenous Dayak communities are celebrated side by side.', 'Visitors can expect to explore a mix of heritage landmarks, bustling markets, and scenic river views. Popular stops include the Kuching Waterfront, a vibrant promenade perfect for photos and evening strolls; the Cat Museum, a quirky attraction highlighting the city''s feline symbol; and the Sarawak Museum Complex, which provides insight into the state’s history, ethnography, and natural heritage. The tour often includes visits to historic Chinese temples such as Tua Pek Kong Temple, as well as Malay kampungs that showcase traditional stilt houses along the riverbanks.\r\n\r\nDepending on the itinerary, you may also explore local markets like Satok Weekend Market or sample Sarawak’s famous delicacies such as kolo mee and Sarawak laksa. A city tour is not just about sightseeing but also about understanding Kuching’s unique character, where modern cafes sit beside century-old shophouses and diverse communities live harmoniously. Expect a day filled with culture, history, and plenty of opportunities to soak in the laid-back charm that makes Kuching such a memorable destination.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d255254.01071463182!2d110.04323639453126!3d1.557695400000004!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31fba7ee47392245%3A0xed168820e591d4c1!2sParadesa%20Borneo%20-%20Travel%20%26%20Tour!5e0!3m2!1sen!2smy!4v1757231805491!5m2!1sen!2smy'),
(48, 'The Wind Cave Nature', 1.00, 1.00, 5.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/cave.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/cave2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/cave3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/cave4.jpg', 'The Wind Cave Nature Reserve, located near Bau town about 30 minutes from Kuching, is a fascinating natural attraction that combines geological wonder with rich biodiversity. The cave takes its name from the cool breeze that flows through its chambers, offering visitors a refreshing experience as they explore its dark passageways. Unlike heavily commercialized caves, Wind Cave retains much of its natural charm, making it a favorite for those who enjoy quiet exploration, eco-tourism, and a glimpse into Sarawak’s hidden underground landscapes.', 'Inside the cave, visitors can expect a network of wooden walkways and bridges that guide them safely through the dimly lit tunnels. Bring a flashlight or headlamp, as parts of the cave are kept dark to preserve its natural environment. The chambers reveal dramatic limestone formations, stalactites, and stalagmites, while colonies of bats roost high above, creating a unique atmosphere filled with the sounds of fluttering wings.\r\n\r\nNature lovers will also appreciate the reserve’s surroundings—lush forests along the Sarawak River that provide a habitat for birds, insects, and small wildlife. Many visitors pair their trip to Wind Cave with the nearby Fairy Cave, creating a full day of adventure exploring two contrasting cave systems. Expect a serene yet adventurous journey where you’ll walk through echoing chambers, feel the natural breeze, and connect with one of Sarawak’s quieter but equally enchanting natural sites.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3988.6026080222387!2d110.13492837472477!3d1.4144496985722064!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31fb6d5943080859%3A0xce4d0f128cf3034b!2sWind%20Caves!5e0!3m2!1sen!2smy!4v1757232103408!5m2!1sen!2smy'),
(13, 'Langkawi Sky Cab', 40.00, 40.00, 50.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/skycab.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/skycab2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/skycab3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/skycab4.jpg', 'The Langkawi SkyCab is one of the island’s most iconic attractions, offering breathtaking panoramic views of Langkawi’s lush rainforests, dramatic cliffs, and turquoise Andaman Sea. Located at the base of Gunung Mat Cincang, the cable car ride takes visitors up one of the oldest rock formations in Southeast Asia, dating back over 550 million years. It’s not just a transportation experience—it’s a thrilling journey that combines natural beauty with a touch of adventure.', 'Visitors can expect a ride that is both exhilarating and scenic. The SkyCab ascends steeply over the rainforest canopy, providing stunning aerial views at every angle. At the middle station, you can step out to admire the landscape and snap photos of Langkawi''s diverse terrain. The ride continues to the top station, where observation decks reveal sweeping vistas of the islands, sea, and even the mountains of southern Thailand on clear days.\r\n\r\nFor those seeking more excitement, the attraction is connected to the Langkawi SkyBridge, a curved pedestrian suspension bridge that hangs dramatically above the jungle, offering a truly unforgettable walking experience. The SkyCab complex also features other attractions such as a 3D art museum, sky dome, and immersive activities, making it suitable for families and thrill-seekers alike. Expect a mix of awe, wonder, and adventure as you ride one of the steepest cable cars in the world and enjoy one of Langkawi’s most celebrated highlights.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3965.1773796535026!2d99.66910367475197!3d6.371086193619144!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x304c76e12f53df01%3A0xe2551c0b7d23ba7e!2sLangkawi%20Skybridge%20Cable%20Car!5e0!3m2!1sen!2smy!4v1757232400273!5m2!1sen!2smy'),
(14, 'Dream Forest Langkawi', 68.00, 50.00, 88.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/dreamforest.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/dreamforest2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/dreamforest3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/dreamforest4.jpg', 'Dream Forest Langkawi is an enchanting, immersive attraction that blends nature, technology, and local folklore into a unique night-time experience. Nestled within a lush tropical forest, this attraction transforms the natural landscape into a magical storytelling journey through state-of-the-art lighting, soundscapes, and interactive features. Inspired by Langkawi’s rich legends and myths—such as tales of Princess Mahsuri and mystical forest spirits—the Dream Forest is designed to transport visitors into a world where culture and fantasy come alive under the stars.', 'Visitors can expect a multi-sensory adventure as they walk along illuminated trails winding through the forest. The environment is brought to life with glowing light installations, artistic projections, and ambient music that create a dreamlike atmosphere. Along the way, you''ll encounter themed zones that highlight famous Langkawi legends, offering both storytelling and visual spectacle.\r\n\r\nUnlike traditional attractions, Dream Forest is less about adrenaline and more about wonder, reflection, and connection with both nature and heritage. It’s perfect for evening strolls, family outings, or couples looking for a romantic, magical experience. Expect to feel as though you’re stepping into a living fairy tale—where the natural forest blends seamlessly with art, myth, and technology.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3965.227158354438!2d99.78868787475176!3d6.364640993625442!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x304c79cb3218b6f9%3A0x1631286c319bb86f!2sDream%20Forest%20Langkawi!5e0!3m2!1sen!2smy!4v1757232669809!5m2!1sen!2smy'),
(15, 'Langkawi Sky Bridge', 6.00, 6.00, 10.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/skybridge.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/skybridge2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/skybridge3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/skybridge4.jpg', 'The Langkawi Sky Bridge is one of the island’s most impressive engineering marvels and a must-visit landmark. Suspended about 660 meters above sea level at the peak of Gunung Mat Cincang, the curved pedestrian bridge stretches 125 meters across lush rainforest valleys. Completed in 2005, it is renowned not only for its dramatic design but also for the breathtaking panoramic views it offers of Langkawi’s mountains, islands, and surrounding sea. The bridge has become a symbol of Langkawi’s adventurous spirit, drawing travelers from around the world to experience walking “above the clouds.”', 'Visitors can expect a thrilling yet safe adventure as they step onto the bridge, which is supported by a single towering pylon and sways gently with the wind. The walkway is wide and comfortable, with steel railings for safety, and features transparent glass panels at certain sections for those who want to look directly down at the forest canopy. The curved design allows for a constantly changing perspective, giving you multiple photo opportunities as you walk along its span.\r\n\r\nTo reach the Sky Bridge, visitors typically ride the Langkawi SkyCab cable car to the top station, then take a short walk or the SkyGlide (inclined lift) to access the bridge. The experience is exhilarating, offering a rare combination of natural beauty and architectural wonder. Expect awe-inspiring views, a dash of adrenaline, and an unforgettable highlight of your Langkawi adventure.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d1982.528583759259!2d99.6607963885245!3d6.386624198400944!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x304c76c41c936fc3%3A0x36f2796db82629c3!2sLangkawi%20Sky%20Bridge!5e0!3m2!1sen!2smy!4v1757233085641!5m2!1sen!2smy'),
(16, 'Crocodile Adventureland Langkawi', 40.00, 30.00, 50.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/crocodile.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/crocodile2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/crocodile3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/crocodile4.jpg', 'Crocodile Adventureland Langkawi, located in Teluk Datai, is one of the largest crocodile adventure parks in Malaysia and home to over 4,000 crocodiles of various species. Spread across beautifully landscaped grounds, this park is not just a tourist attraction but also an educational center, dedicated to the conservation, breeding, and study of crocodiles. It offers visitors a chance to get up close with these prehistoric reptiles in a safe and engaging environment while learning about their unique biology and role in nature.', 'Visitors can expect an exciting combination of education, entertainment, and adventure. The park features a wide variety of crocodiles, from baby hatchlings to massive adult species, including the world''s largest living crocodile in captivity, recognized by the Malaysia Book of Records. Scheduled shows such as the Crocodile Jumping Show and Education Talk Sessions allow guests to witness the agility and power of these creatures while gaining insights into their behavior.\r\n\r\nBeyond the shows, interactive experiences like crocodile feeding sessions and photo opportunities (with baby crocodiles under staff supervision) add to the adventure. The park also includes attractions such as Jurassic Croc, where visitors can learn fascinating facts through engaging displays and themed zones. Expect a mix of thrills and knowledge, making this a memorable stop for families, animal enthusiasts, and anyone curious about these ancient reptiles.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3964.934674471169!2d99.7100626747522!3d6.402418393588261!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x304c7b8a61691f0f%3A0xbfe64119ee00e0c4!2sCrocodile%20Adventureland%20Langkawi!5e0!3m2!1sen!2smy!4v1757233395529!5m2!1sen!2smy'),
(17, 'Langkawi Wildlife Park', 45.00, 30.00, 60.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/wildlifepark.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/wildlifepark2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/wildlifepark3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/wildlifepark4.jpg', 'Langkawi Wildlife Park & Bird Paradise is a family-friendly attraction located just a short drive from Kuah Town. Opened in 2002, it is Malaysia’s first fully-covered wildlife park, making it an all-weather destination. The park is home to over 150 species of animals and birds from around the world, set in beautifully landscaped surroundings with waterfalls, ponds, and interactive enclosures. Its mission goes beyond entertainment, aiming to promote conservation awareness and provide an educational experience about the natural world.', 'Visitors can expect a close-up, interactive encounter with a wide variety of wildlife. One of the highlights is the walk-in aviary, where colorful parrots, flamingos, and peacocks roam freely, allowing for memorable photo opportunities. The park offers a unique feeding experience, where guests can hand-feed deer, raccoons, ostriches, rabbits, and even certain species of birds under supervision, making it especially enjoyable for children.\r\n\r\nBeyond birds, the park houses reptiles, mammals, and aquatic animals, offering an engaging mix for visitors of all ages. Knowledgeable staff are available to share interesting facts during feeding sessions and guided interactions, ensuring both fun and learning. With its sheltered design, the park remains comfortable to explore regardless of rain or shine. Expect a relaxed, family-oriented adventure that combines up-close encounters, educational fun, and plenty of Instagram-worthy moments.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3965.0492558995747!2d99.85959677475202!3d6.387645493602808!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x304c7e7cb2068ad1%3A0xb690edda82e141ec!2sLangkawi%20Wildlife%20Park!5e0!3m2!1sen!2smy!4v1757233702474!5m2!1sen!2smy'),
(10, 'Tanjung Piai National Park', 16.00, 10.00, 20.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/piai.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/piai2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/piai3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/piai4.jpg', 'Tanjung Piai National Park, located in the southernmost tip of Peninsular Malaysia (and mainland Asia), is a unique ecological gem in Johor. Covering over 900 hectares, it is best known for its extensive mangrove forests and mudflats, which provide a crucial habitat for migratory birds, marine life, and coastal wildlife. The park is also a designated Ramsar Wetland Site, highlighting its international importance for conservation. Beyond its ecological significance, Tanjung Piai is symbolically important as the “southernmost point of mainland Asia,” marked by a monument that draws visitors eager to stand at this geographic landmark.', 'Visitors can expect a peaceful and educational experience walking along the park''s wooden boardwalks, which stretch deep into mangrove forests and open up to coastal viewing platforms. Along the way, interpretive signboards explain the importance of mangroves and their role in protecting shorelines from erosion while serving as nurseries for fish, crabs, and shrimp. Wildlife spotting is a highlight—visitors may encounter mudskippers, crabs, monitor lizards, and occasionally migratory birds like herons and kingfishers.\r\n\r\nAt the park''s southernmost tip, a large globe monument marks Tanjung Piai''s claim as the furthest point south on mainland Eurasia—a popular spot for photos. The park also offers visitor facilities such as rest huts, a visitor center, and guided tours for those who want deeper insights. Expect a calm, nature-focused outing that combines eco-education with the thrill of standing at one of Asia’s most symbolic geographical landmarks.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3988.8411022065447!2d103.50689767472447!3d1.2681355987198015!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31d0a999e232063f%3A0x9ea9f9581f2ca360!2sTaman%20Negara%20Johor%20Tanjung%20Piai!5e0!3m2!1sen!2smy!4v1757235428727!5m2!1sen!2smy'),
(11, 'Putuo Village', 10.00, 10.00, 10.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/putuo.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/putuo2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/putuo3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/putuo4.jpg', 'Putuo Village, located in Kulai, Johor, is a serene cultural and spiritual attraction that blends Buddhism, nature, and wellness. Inspired by China’s Mount Putuo, a sacred Buddhist site, the village was established to promote harmony, mindfulness, and appreciation of nature. It offers a peaceful retreat away from the city, featuring beautiful gardens, meditation spaces, and cultural displays that highlight Buddhist teachings and practices. The village is especially popular during festive seasons, such as Chinese New Year and Mid-Autumn Festival, when it transforms into a vibrant space filled with lights, decorations, and cultural activities.', 'Visitors can expect a calm and enriching experience as they stroll through themed areas such as the Zen Garden, Bamboo Forest Trail, and Wishing Tree. Spiritual elements like prayer wheels, meditation halls, and Buddha statues provide opportunities for reflection, while the natural surroundings create a soothing atmosphere.\r\n\r\nPutuo Village is also known for its seasonal highlights, especially the Lantern Festival, when thousands of colorful lanterns light up the night, creating a magical and Instagram-worthy scene. Wellness activities such as meditation workshops and vegetarian dining options are also part of the experience, making it ideal for visitors seeking relaxation and inner peace. Expect a blend of culture, spirituality, and natural beauty that offers both tranquility and inspiration.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3988.00999520134!2d103.62306897472538!3d1.7251057982589664!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31da7c1fbdc98ffd%3A0x5ddc645759e24d8f!2sPutuo%20Village!5e0!3m2!1sen!2smy!4v1757235790500!5m2!1sen!2smy'),
(12, 'Zoo Johor', 10.00, 10.00, 15.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/zoojohor.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/zoojohor2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/zoojohor3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/zoojohor4.jpg', 'Johor Zoo, located in the heart of Johor Bahru, is one of the oldest zoos in Malaysia, established in 1928 by the late Sultan Ibrahim. Originally a private menagerie, it was later opened to the public and has since become a popular family destination. The zoo is home to a diverse collection of animals and birds from both local and international species, set within a lush and accessible environment. Its central location makes it a convenient stop for both locals and tourists exploring Johor Bahru city.', 'Visitors can expect a family-friendly outing with opportunities to see a wide variety of animals including lions, elephants, tigers, flamingos, crocodiles, and monkeys. The zoo features open enclosures and aviaries, allowing for closer viewing while still maintaining safety. Feeding sessions and interaction areas with smaller animals, such as rabbits and deer, add an engaging touch for children.\r\n\r\nThe zoo is designed for leisurely exploration, with shaded pathways, gardens, and rest areas for families. It also has basic facilities like food stalls and playgrounds, making it suitable for a half-day visit. While it is smaller compared to larger modern wildlife parks, Johor Zoo offers an affordable and accessible way to experience wildlife up close. Expect a relaxed outing where education, family fun, and a touch of nostalgia come together.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3988.5274152039938!2d103.74960937472481!3d1.4575381985287492!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31da12c0c23e30a5%3A0xa883a3a1954008b4!2sJohor%20Zoo!5e0!3m2!1sen!2smy!4v1757235982921!5m2!1sen!2smy'),
(31, 'The Banjaran Hotsprings Retreat', 350.00, 300.00, 400.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/hotsprings.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/hotsprings2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/hotsprings3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/hotsprings4.jpg', 'The Banjaran Hotsprings Retreat, located in Ipoh, Perak, is Malaysia’s first luxury natural hot springs wellness retreat. Nestled amidst 22 acres of lush rainforest, limestone hills that are over 260 million years old, and geothermal hot springs, it offers an exclusive sanctuary for rest, rejuvenation, and holistic healing. This award-winning retreat is designed for adults seeking peace and privacy, making it a popular destination for honeymooners, wellness travelers, and those craving a tranquil escape from the hustle and bustle of daily life.', 'Visitors can expect a serene and luxurious experience centered around wellness and nature. The retreat offers private villas with plunge pools and hot tubs fed by natural geothermal waters, ensuring complete seclusion and comfort. Guests can immerse themselves in unique facilities such as the thermal hot springs dipping pools, the Meditation Cave, the Crystal Cave, and the Doctor Fish Pool, each designed to promote relaxation and inner balance.\r\n\r\nThe Banjaran also houses award-winning dining experiences, most notably Jeff’s Cellar, a fine-dining restaurant set within a magnificent limestone cave, offering a one-of-a-kind gastronomic journey. Wellness services include holistic spa treatments, yoga, and meditation, all designed to harmonize the mind, body, and soul.\r\n\r\nExpect a retreat that combines untouched natural beauty with five-star luxury—an oasis where healing waters, mystical caves, and lush greenery converge to create an unforgettable and transformative getaway.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3976.7924952967687!2d101.1535504747384!3d4.631076095343698!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31caf2aa9eb6776f%3A0x1e9e1cb7c79e0ed9!2sThe%20Banjaran%20Hotsprings%20Retreat!5e0!3m2!1sen!2smy!4v1757236258418!5m2!1sen!2smy'),
(32, 'Sunway Lost World of Tambun', 80.00, 70.00, 90.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/tambun.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/tambun2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/tambun3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/tambun4.jpg', 'Sunway Lost World of Tambun, located in Ipoh, Perak, is a premier theme park and resort built around natural hot springs, stunning limestone cliffs, and lush rainforest. It combines the excitement of amusement rides, water attractions, and adventure activities with the unique charm of Perak’s natural heritage. The park is more than just an amusement destination—it’s also a place to relax, learn, and connect with nature. With its variety of themed zones, Lost World of Tambun caters to families, thrill-seekers, and wellness travelers alike.', 'Visitors can expect a full day (or even two) of diverse attractions spread across multiple themed areas:\r\n\r\nWater Park – Featuring giant water slides, wave pools, and a lazy river perfect for cooling off in the tropical heat.\r\n\r\nAmusement Park – Complete with roller coasters, carousels, and funfair-style rides for both kids and adults.\r\n\r\nAdventure Park – Offering outdoor activities such as zip-lining, rock climbing, and cave explorations.\r\n\r\nTiger Valley & Petting Zoo – A mix of wildlife encounters, from majestic Siberian tigers to small animals like raccoons, rabbits, and birds.\r\n\r\nHot Springs Night Park – One of the highlights, where visitors can relax in geothermal pools under the stars, enjoy the glowing Luminous Forest, and watch cultural performances.\r\n\r\nDining and accommodation options are available within the park, making it convenient for multi-day stays. Expect a vibrant blend of adrenaline, family fun, and relaxation, all set against the breathtaking backdrop of Ipoh’s limestone hills.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3976.823923477987!2d101.15192222473839!3d4.625482845349275!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31caed5bca279cdf%3A0x408a253cdbfcbb2d!2sLost%20World%20of%20Tambun!5e0!3m2!1sen!2smy!4v1757236462034!5m2!1sen!2smy'),
(33, 'Kampar White Water Rafting', 155.00, 120.00, 175.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/raft.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/raft2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/raft3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/raft4.jpg', 'Kampar White Water Rafting, located in Gopeng, Perak, is one of Malaysia’s most popular river adventures, drawing thrill-seekers and nature lovers alike. The Kampar River is fed by streams from the surrounding Titiwangsa Range, creating a dynamic waterway with exciting rapids and scenic stretches of calmer currents. Surrounded by lush rainforest and dotted with historical tin mining sites, the area combines adrenaline-pumping adventure with natural and cultural charm.', 'Visitors can expect an exhilarating outdoor experience navigating through Grade I–III rapids, which are suitable for beginners and intermediate rafters. Guided by professional instructors, participants paddle through rushing waters, bounce over waves, and occasionally take breaks at calmer sections to enjoy the pristine jungle scenery and refreshing river water.\r\n\r\nSafety equipment, including helmets and life jackets, is provided, and basic training is given before the journey begins, making the activity accessible even to first-timers. Along the way, you may spot unique flora, small waterfalls, and remnants of old tin mining structures that tell the story of Gopeng’s heritage.\r\n\r\nDepending on the package, the adventure may also include river tubing, body rafting, or team-building activities, making it a great choice for groups. Expect a half-day of thrills, teamwork, and immersion in nature—an unforgettable way to experience Perak’s great outdoors.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3977.826271521596!2d101.1966295747372!3d4.443412195530835!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31cafaa531ee852f%3A0x9d98e29ee9a327f7!2sGopeng%20White%20Water%20Rafting!5e0!3m2!1sen!2smy!4v1757236613928!5m2!1sen!2smy'),
(34, 'Zoo Taiping and Night Safari', 16.00, 16.00, 20.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/safari.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/safari2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/safari3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/safari4.jpg', 'Zoo Taiping, located in Perak, is Malaysia’s first and oldest zoo, established in 1961. Nestled within the lush Taiping Lake Gardens at the foothills of Bukit Larut (Maxwell Hill), it houses over 1,200 animals representing more than 140 species of mammals, reptiles, birds, and fish. Its natural rainforest setting makes it one of the most scenic and eco-friendly zoos in the country. The highlight is its Night Safari, the first of its kind in Malaysia, where visitors can observe nocturnal animals in action under special lighting that mimics moonlight.', 'During the day, visitors can stroll or take a tram ride through well-designed enclosures featuring tigers, elephants, orangutans, giraffes, and many more. The zoo emphasizes conservation and education, making it family-friendly and ideal for school trips.\r\n\r\nAs evening falls, the Night Safari offers a whole new perspective. Instead of sleeping animals, guests witness the natural behavior of nocturnal creatures such as lions, leopards, owls, and civets as they hunt, forage, or roam. The experience is enhanced by ambient sounds of the forest, giving it a more authentic jungle atmosphere than a typical zoo visit.\r\n\r\nWith its mix of history, conservation focus, and unique nighttime experience, Zoo Taiping & Night Safari is both educational and adventurous—perfect for animal lovers and curious explorers.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3975.5031810740297!2d100.74845707473986!3d4.854995095120629!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31caae43f7ef5bef%3A0xf38ffb8364bed3e0!2sZoo%20Taiping%20%26%20Night%20Safari!5e0!3m2!1sen!2smy!4v1757237322697!5m2!1sen!2smy'),
(35, 'Kellie\s Castle', 9.00, 9.00, 15.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/castle.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/castle2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/castle3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/castle4.jpg', 'Kellie’s Castle, located near Batu Gajah in Perak, is one of Malaysia’s most mysterious and romantic landmarks. Built by Scottish planter William Kellie Smith in the early 20th century, the castle was intended as a grand home inspired by Scottish, Moorish, and Indian architecture. However, construction was never completed due to Smith’s untimely death, leaving the castle shrouded in legends and tales of unfinished dreams. Today, it stands as a popular heritage attraction, drawing visitors with its intriguing history, unique design, and rumored supernatural presence.', 'Visitors can wander through the castle’s many rooms, corridors, and hidden passageways, imagining the grandeur it was meant to embody. Highlights include the grand hall, the rooftop with panoramic views of the surrounding countryside, and the mysterious underground tunnels said to connect to nearby temples.\r\n\r\nThe unfinished structure, combined with ivy-covered walls and haunting tales of William Kellie Smith’s spirit, gives the site an almost gothic charm. History buffs will enjoy learning about its colonial past, while photography enthusiasts will find plenty of picturesque spots both inside and outside the castle.\r\n\r\nWhether you’re drawn by the history, the architecture, or the ghost stories, Kellie’s Castle offers a fascinating step back in time and a glimpse into one man’s unfulfilled vision.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3977.658193701596!2d101.08519497473743!3d4.474458495499847!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31caef5e78817aa9%3A0x93bc5c7d6ecd82ba!2sKellie’s%20Castle!5e0!3m2!1sen!2smy!4v1757237651016!5m2!1sen!2smy'),
(36, 'Gaharu Tea Valley', 13.00, 10.00, 17.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/teavalley.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/teavalley2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/teavalley3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/teavalley4.jpg', 'Gaharu Tea Valley, located in Gopeng, Perak, is a unique agro-tourism destination surrounded by over 200,000 gaharu (agarwood) trees. Known for its medicinal and aromatic properties, agarwood has been treasured for centuries in traditional medicine, incense, and perfumes. The valley combines nature, culture, and wellness, offering visitors the chance to learn about the history and uses of this remarkable tree while enjoying a peaceful escape into lush greenery.', 'Guests can take a guided tour around the plantation, where they’ll discover the different types of gaharu trees and the careful process of cultivating them. Highlights include the Lover’s Tree, believed to bring blessings for couples, and the Great Wall of Gopeng, a unique structure built for protection and symbolic beauty.\r\n\r\nVisitors can also try refreshing gaharu tea, known for its calming and health-boosting benefits, or shop for gaharu-based products such as cookies, noodles, and essential oils. The serene landscape makes it an ideal spot for relaxation, photos, and a deeper appreciation of sustainable farming practices.\r\n\r\nWhether you’re interested in health, culture, or just a tranquil retreat into nature, Gaharu Tea Valley offers a distinctive experience that blends tradition with eco-tourism.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3977.7413226201816!2d101.19032347473733!3d4.459130395515144!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31cafa925055fc65%3A0x268dae88c39b3798!2sHOGA%2C%20Gaharu%20Tea%20Valley%20Gopeng!5e0!3m2!1sen!2smy!4v1757238042289!5m2!1sen!2smy'),
(19, 'Genting Skyworlds Theme Park', 168.00, 140.00, 175.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/genting.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/genting2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/genting3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/genting4.jpg', 'Genting SkyWorlds is a world-class outdoor theme park located at Resorts World Genting in Pahang. Opened in 2022, it features nine themed worlds inspired by movies and adventure stories, bringing together cutting-edge rides, immersive attractions, and cinematic experiences. Nestled in the cool highlands at over 6,000 feet above sea level, the park combines entertainment with a refreshing escape from the city’s heat.\r\n\r\n', 'Visitors can look forward to a fun-filled day packed with thrills, family-friendly rides, and live entertainment. The park’s nine themed zones include Eagle Mountain, Ice Age, Liberty Lane, Epic, and more—each designed with meticulous detail to transport guests into different worlds. From adrenaline-pumping roller coasters and motion-simulator rides to interactive shows and kids’ attractions, there’s something for every age group.\r\n\r\nOne of the highlights is the Mad Ramp Peak – Full Throttle Racing coaster, a high-speed ride perfect for thrill-seekers. Families and younger visitors can enjoy gentler experiences like the Ice Age Adventure boat ride or fun games scattered around the park. Visitors will also find immersive street performances, photo-worthy backdrops, and themed dining outlets offering a variety of cuisines to keep energy levels high.\r\n\r\nWith its combination of modern technology, engaging storytelling, and a cool mountain atmosphere, Genting SkyWorlds promises more than just rides—it delivers an immersive adventure. Guests should plan for at least half a day to explore the park fully, as there’s plenty to see, do, and enjoy for both kids and adults alike.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3982.7041838866508!2d101.79137067473158!3d3.4220528965524886!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31cc1400dc4f3e75%3A0x1ec43c62c7525ccb!2sGenting%20SkyWorlds%20Theme%20Park!5e0!3m2!1sen!2smy!4v1757581253152!5m2!1sen!2smy'),
(20, 'Cameron Highland Flora Park', 50.00, 25.00, 60.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/florapark.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/florapark2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/florapark3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/florapark4.jpg', 'Cameron Highland Flora Park is a vibrant floral paradise tucked away in the cool highlands of Pahang. Famous for its breathtaking landscapes, the park showcases a vast collection of colorful blooms and ornamental plants, making it one of the most picturesque destinations in the Cameron Highlands. Surrounded by fresh mountain air and rolling hills, the park is a must-visit spot for nature lovers, photographers, and anyone looking for a peaceful escape.', 'Visitors will be greeted by an explosion of colors as they wander through beautifully arranged gardens filled with roses, daisies, sunflowers, hydrangeas, and many other highland plants. The park features themed floral sections, landscaped paths, and viewing platforms that overlook the lush valleys and mountains beyond.\r\n\r\nOne of the highlights is the panoramic hilltop view, where visitors can relax and soak in the stunning scenery while enjoying the refreshing highland breeze. For those who love taking pictures, every corner of the park is designed to be “Instagrammable,” with charming floral arches, gazebos, and carefully curated flower displays.\r\n\r\nThe park also offers cozy resting areas where guests can sit and enjoy the calm atmosphere, as well as a small café serving light refreshments. It’s a great place for families, couples, or groups of friends to spend a leisurely day surrounded by nature’s beauty.\r\n\r\nCameron Highland Flora Park is more than just a garden—it’s a tranquil retreat where you can admire the artistry of landscaping, breathe fresh mountain air, and create lasting memories in one of Malaysia’s most scenic highland attractions.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3977.519072070233!2d101.40961877473757!3d4.4999944954743905!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31ca59dcf492e19d%3A0x9a95a6174dc3d667!2sCameron%20Highlands%20Flora%20Park!5e0!3m2!1sen!2smy!4v1757243137815!5m2!1sen!2smy'),
(21, 'The Sheep Sanctuary Cameron Highland', 12.00, 0.00, 15.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/sheep.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/sheep2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/sheep3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/sheep4.jpg', 'The Sheep Sanctuary, located in Kea Farm, Cameron Highlands, is a charming family-friendly attraction that brings a touch of New Zealand’s countryside to Malaysia’s cool highlands. Surrounded by rolling hills and refreshing mountain air, the sanctuary is home to fluffy, well-kept sheep that freely roam around in open enclosures. It’s one of the most delightful spots for both children and adults to interact with animals while enjoying a unique pastoral experience.', 'Visitors can look forward to hands-on interaction with sheep, from feeding them pellets to gently petting their soft wool. The sanctuary provides food that guests can purchase to feed the animals, making it especially enjoyable for children who get to experience farm life up close. Watching the sheep graze, play, and roam in a relaxed highland setting creates a calming and heartwarming experience.\r\n\r\nBesides the sheep, the sanctuary also features scenic spots for photography. With its cute farm-themed décor, rustic wooden fences, and flower-lined paths, it’s an ideal place for memorable family photos and couple shots. Some areas even offer elevated views of the surrounding highlands, making it perfect for nature lovers and photo enthusiasts.\r\n\r\nThe Sheep Sanctuary is not a large-scale attraction, but its cozy atmosphere and unique concept make it a great stopover as part of a Cameron Highlands itinerary. After visiting, guests can also explore nearby Kea Farm Market for local produce, flowers, and souvenirs.\r\n\r\nWhether you’re an animal lover, a family with kids, or simply looking for a relaxing stop in the highlands, The Sheep Sanctuary offers a simple yet delightful experience that brings joy and smiles.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3977.4968167223365!2d101.40480797473758!3d4.504066095470324!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31ca573f0cfba017%3A0x9439a3524b5bf559!2sThe%20Sheep%20Sanctuary!5e0!3m2!1sen!2smy!4v1757243439094!5m2!1sen!2smy'),
(22, 'Bukit Tinggi', 14.00, 10.00, 20.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/bukittinggi.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/bukittinggi2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/bukittinggi3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/bukittinggi4.jpg', 'Bukit Tinggi, also known as Berjaya Hills, is a charming highland resort destination located in Bentong, Pahang, just about an hour’s drive from Kuala Lumpur. Perched at 2,500 feet above sea level, it offers cool weather, scenic landscapes, and a mix of cultural and recreational attractions. The most famous highlight is the Colmar Tropicale, a French-themed village modeled after the 16th-century town of Colmar in Alsace, France, complete with cobblestone streets, colorful buildings, and European-style cafés.', 'Visitors can start their journey by exploring Colmar Tropicale, strolling along its quaint streets, taking photos with the beautiful European-style architecture, and enjoying a taste of France in Malaysia. There are cafés, bakeries, and restaurants offering both Western and local delicacies, making it a cozy spot for families and couples alike.\r\n\r\nBeyond Colmar Tropicale, Bukit Tinggi offers a variety of attractions. The Japanese Village, set within lush rainforest greenery, features a serene tea house, koi ponds, and beautiful landscaped gardens where guests can experience authentic Japanese culture. Visitors can even dress in traditional yukata for a more immersive experience.\r\n\r\nNature lovers can also explore the Botanical Garden with its rich collection of tropical and exotic plants, while adventure seekers may enjoy outdoor activities such as horse riding, trekking, or archery. The cool climate and scenic setting make the entire area perfect for relaxation, photography, and a refreshing escape from city life.\r\n\r\nWith its unique blend of French elegance, Japanese tranquility, and natural beauty, Bukit Tinggi provides a diverse experience in one destination—ideal for a day trip or a peaceful weekend getaway.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d31862.5059499565!2d101.82475238906088!3d3.395713781043155!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31cc171c2943b275%3A0xac226a890a1e1fe8!2sBukit%20Tinggi%2C%2028750%20Bentong%2C%20Pahang!5e0!3m2!1sen!2smy!4v1757243544053!5m2!1sen!2smy'),
(23, 'Genting Skytropolis Indoor Theme Park', 63.00, 50.00, 80.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/skytropolis.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/skytropolis2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/skytropolis3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/skytropolis4.jpg', 'Genting Skytropolis Indoor Theme Park is a vibrant, family-friendly attraction located within First World Plaza at Resorts World Genting. Spanning over 400,000 square feet, this colorful indoor park is filled with rides and attractions suitable for all ages. Its lively carnival-like atmosphere, bright neon lights, and variety of entertainment options make it a must-visit destination for families, couples, and groups seeking fun in the cool highlands.', 'Visitors can expect a mix of thrill rides, family rides, and children’s attractions spread across multiple zones. For adrenaline seekers, rides like the Super Glider, a suspended roller coaster, and the Spin Crazy pendulum ride will deliver high-speed excitement. Families can enjoy gentler rides such as the Copper Express train, the Sky Towers drop ride, or a spin on the Bumper Cars. For younger children, there are plenty of kiddie rides, carousels, and interactive attractions designed to keep them entertained.\r\n\r\nOne of the best features of Skytropolis is that it’s completely indoors, making it a perfect choice for rainy days or when you want a break from the outdoor chill of Genting Highlands. The theme park also operates on a pay-per-ride or unlimited pass system, giving visitors flexibility depending on how long they plan to stay.\r\n\r\nSurrounded by shopping, dining outlets, and other entertainment options within First World Plaza, it’s easy to combine a visit to Skytropolis with other activities. Families can enjoy a full day exploring rides, grabbing meals at nearby restaurants, and even catching performances or attractions located within the same complex.\r\n\r\nWith its colorful design, variety of rides, and convenient indoor setting, Genting Skytropolis Indoor Theme Park is a fun-packed destination where the whole family can create exciting memories together.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3982.69291301491!2d101.7922888747316!3d3.4247633965497712!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31cc1547e3860b5b%3A0x4bef504984d2830b!2sSkytropolis%20Indoor%20Theme%20Park!5e0!3m2!1sen!2smy!4v1757243880646!5m2!1sen!2smy'),
(24, 'Fraser Hill', 13.00, 10.00, 18.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/fraser.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/fraser2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/fraser3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/fraser4.jpg', 'Frasers Hill, located on the border of Selangor and Pahang, is a charming colonial-era hill station known for its cool climate, lush greenery, and tranquil atmosphere. Perched at about 1,200 meters above sea level, the hill was once a British colonial retreat and still retains its old-world charm with English-style cottages, flower gardens, and winding mountain roads. Often called a “Little England” in Malaysia, Fraser Hill is a peaceful escape for nature lovers, birdwatchers, and those seeking a break from city life.', 'Visitors to Frasers Hill can look forward to a wide range of relaxing and outdoor activities. The hill is famous for its birdwatching, hosting the annual International Bird Race and being home to over 250 bird species. Nature enthusiasts can explore its jungle trails, such as the Bishop Trail and Hemmant Trail, which take you through serene rainforests filled with flora and fauna.\r\n\r\nFor those who prefer leisure, the Clock Tower at the town center is an iconic photo spot, surrounded by quaint shops, cafés, and English-style architecture. Families can enjoy paddle boating at Allen Water Lake, a small but charming attraction, or visit the flower gardens to admire colorful blooms. Golf lovers can also try out the Frasers Hill Golf Club, one of the oldest courses in Malaysia.\r\n\r\nUnlike the busier Genting or Cameron Highlands, Frasers Hill offers a slower pace with a focus on tranquility and nature appreciation. The cool mountain air, misty mornings, and scenic views make it a perfect getaway for couples, families, or anyone who wants to unwind in a refreshing environment.\r\n\r\nWhether youre hiking, birdwatching, or simply enjoying tea in a colonial-style café, Fraser''s Hill provides a nostalgic highland experience where history, nature, and relaxation blend seamlessly.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d31851.762716541998!2d101.71916683916136!3d3.7070423110760067!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31cbf4e2c3261e61%3A0xe270502734b6ffb4!2sFraser&#39;s%20Hill%2C%20Pahang!5e0!3m2!1sen!2smy!4v1757243979709!5m2!1sen!2smy'),
(7, 'LEGOLAND Malaysia Ticket', 105.00, 80.00, 150.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/legoland.jpg','https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/legoland2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/legoland3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/legoland4.jpg', 'Legoland Malaysia Resort, located in Johor Bahru, is a premier family-friendly theme park and resort dedicated to the world of LEGO. Opened in 2012, it is the first Legoland park in Asia and offers a unique blend of interactive rides, shows, and attractions designed to inspire creativity and imagination among children and adults alike. The resort features themed zones, including Miniland, where iconic landmarks are recreated using millions of LEGO bricks, as well as various rides and play areas that cater to different age groups.', 'Visitors can expect a fun-filled day packed with excitement and adventure. The park is divided into several themed areas such as LEGO City, Adventure Land, Imagination Zone, and LEGO Ninjago World, each offering a variety of rides and activities. From thrilling roller coasters and water rides to interactive building stations and live shows, there’s something for everyone.\r\n\r\nMiniland is a highlight of the park, showcasing detailed LEGO models of famous landmarks from around the world, including the Petronas Towers, Singapore’s Marina Bay Sands, and even local Malaysian icons. It’s a fascinating display that captivates both kids and adults.\r\n\r\nIn addition to the theme park, Legoland Malaysia Resort also includes a water park with slides and wave pools, as well as a hotel designed with LEGO-themed rooms and amenities. This makes it convenient for families to extend their stay and fully immerse themselves in the LEGO experience.\r\n\r\nWith its combination of fun rides, creative play areas, and immersive environments, Legoland Malaysia Resort is an ideal destination for families looking to create lasting memories together.','https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3988.580529605651!2d103.62691427472468!3d1.427236398559327!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31da0b8c3c76ed33%3A0x815b08d21944354b!2sLEGOLAND%20Malaysia!5e0!3m2!1sen!2smy!4v1757822065772!5m2!1sen!2smy'),
(8, 'Adventure Waterpark Desaru Coast Ticket', 85.00, 70.00, 100.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/desaru.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/desaru2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/desaru3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/desaru4.jpg', 'Adventure Waterpark Desaru Coast, located in the Desaru Coast area of Johor, Malaysia, is a thrilling water park that offers a variety of exciting rides and attractions for visitors of all ages. As part of the larger Desaru Coast development, which includes luxury resorts and beautiful beaches, the water park provides a fun-filled escape with its tropical-themed environment and state-of-the-art facilities. It is designed to cater to families, groups of friends, and adventure seekers looking for a day of aquatic fun.', 'Visitors can expect a wide range of water attractions that cater to different thrill levels. The park features adrenaline-pumping rides such as the Cyclone, a high-speed water slide that twists and turns, and the Wave Pool, which simulates ocean waves for a beach-like experience. For those seeking more relaxed fun, there are lazy rivers where guests can float along gently while enjoying the lush surroundings.\r\n\r\nChildren are well catered for with dedicated play areas that include smaller slides, splash zones, and interactive water features. The park also offers cabanas and shaded areas for families to relax and take breaks between activities.\r\n\r\nIn addition to the rides, Adventure Waterpark Desaru Coast provides various dining options, souvenir shops, and locker rentals to enhance the visitor experience. Safety is a top priority, with trained lifeguards stationed throughout the park to ensure everyone has a safe and enjoyable time.\r\n\r\nWhether you’re looking for thrilling water slides or a leisurely day by the pool, Adventure Waterpark Desaru Coast offers a refreshing and entertaining experience in a beautiful coastal setting.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3988.380987543028!2d104.258970174725!3d1.5379873984476369!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31da4b681875aaff%3A0x60e2925763916144!2sAdventure%20Waterpark%20Desaru%20Coast!5e0!3m2!1sen!2smy!4v1758201243637!5m2!1sen!2smy'),
(9, 'Skyscape at Menara Jland Ticket', 28.00, 20.00, 35.00, 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/skyscape.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/skyscape2.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/skyscape3.jpg', 'https://travel-itinerary-malcolm.s3.ap-southeast-1.amazonaws.com/images/skyscape4.jpg', 'Skyscape at Menara JLand, located in Kuala Lumpur, Malaysia, is a modern observation deck that offers panoramic views of the city’s skyline. Situated atop the Menara JLand building, it provides visitors with a unique vantage point to see iconic landmarks such as the Petronas Twin Towers, KL Tower, and the bustling cityscape below. The observation deck is designed to be an accessible and enjoyable experience for tourists and locals alike, combining stunning views with interactive elements and amenities.', 'Visitors can expect a breathtaking experience as they ascend to the observation deck, where they can take in 360-degree views of Kuala Lumpur. The deck features floor-to-ceiling glass walls, allowing for unobstructed views and excellent photo opportunities. On clear days, visitors can see as far as the surrounding hills and beyond.\r\n\r\nIn addition to the views, Skyscape offers interactive displays that provide information about the city’s history, culture, and architecture. There are also telescopes available for a closer look at specific landmarks. The deck is equipped with comfortable seating areas where guests can relax and enjoy the scenery.\r\n\r\nFor those looking to extend their visit, there is a café on-site where visitors can enjoy refreshments while taking in the views. The atmosphere is family-friendly, making it an ideal spot for couples, families, and solo travelers.\r\n\r\nWhether you’re a first-time visitor to Kuala Lumpur or a local looking for a new perspective on your city, Skyscape at Menara JLand offers a memorable experience with its stunning vistas and engaging features.', 'https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d3988.5147235941895!2d103.75946567472488!3d1.4646859985215437!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x31da13da9d114593%3A0x41d13b2187462476!2sSkyscape%20Johor%20Bahru!5e0!3m2!1sen!2smy!4v1758201641550!5m2!1sen!2smy');

    /*User_Profile Table*/
-- Drop and recreate User_Profile table
DROP TABLE IF EXISTS user_profile;

CREATE TABLE user_profile (
    id INT PRIMARY KEY AUTO_INCREMENT,
    first_name VARCHAR(50),
    last_name VARCHAR(50), 
    email VARCHAR(100) UNIQUE,
    phone VARCHAR(20),
    password VARCHAR(255),
    country VARCHAR(5)
);

    /*Wishlist Table*/
-- Drop and recreate Wishlist table
DROP TABLE IF EXISTS wishlist;

CREATE TABLE wishlist (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    item_id INT NOT NULL, -- Renamed for consistency
    added_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY unique_wishlist (user_id, item_id),
    -- Corrected to reference the 'user_profile' table
    FOREIGN KEY (user_id) REFERENCES user_profile(id) ON DELETE CASCADE
);

    /*Payment_History Table*/
-- Drop and recreate Payment_History table
DROP TABLE IF EXISTS payment_history;

CREATE TABLE payment_history (
    id INT AUTO_INCREMENT PRIMARY KEY,
    user_id INT NOT NULL,
    email VARCHAR(255) NOT NULL,
    purchasedItem_id INT NOT NULL,
    purchasedItem_name VARCHAR(255) NOT NULL,
    visit_date DATE,
    adult_count INT DEFAULT 0,
    youth_count INT DEFAULT 0,
    child_count INT DEFAULT 0,
    foreign_count INT DEFAULT 0,
    image VARCHAR(255) NOT NULL,
    total_amount DECIMAL(10,2) NOT NULL,
    payment_method VARCHAR(50),
    payment_date TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (user_id) REFERENCES user_profile(id),
    FOREIGN KEY (purchasedItem_id) REFERENCES attractions(id)
);

SET FOREIGN_KEY_CHECKS = 1;